bool check_new_id_mapping_permitted(const struct file *file,
                                    struct user_namespace *ns,
                                    int cap_setid,
                                    struct uid_gid_map *new_map) {
    struct user_namespace *parent;
    kuid_t f_kuid;
    kgid_t f_kgid;
    struct inode *inode = file_inode(file);

    if ((new_map->nr_extents == 1) &&
        (new_map->map[0].lower_first == new_map->lowest_mapped) &&
        (new_map->map[0].count == 1)) {
        if (cap_setid == CAP_SETUID) {
            f_kuid = I_UID(inode);
            if (uid_eq(kuid_t_to_uid(f_kuid), current_uid()))
                return true;
        } else {
            f_kgid = I_GID(inode);
            if (gid_eq(kgid_t_to_gid(f_kgid), current_gid()))
                return true;
        }
    }

    if (ns == &init_user_ns)
        return false;

    parent = ns->parent;
    if (!parent)
        return false;

    if (cap_setid == CAP_SETUID)
        return ns_capable(parent, CAP_SETUID);
    else
        return ns_capable(parent, CAP_SETGID);
}

bool check_new_id_mapping(const struct file *file, struct user_namespace *ns,
                          int cap_setid, struct uid_gid_map *new_map) {
    if (new_map->nr_extents == 1) {
        struct uid_gid_map_extent *extent = &new_map->extents[0];
        if (extent->count == 1) {
            // Mapping is a single extent of length one
            if (cap_setid == CAP_SETUID) {
                if (extent->lower_first == current_fsuid()) {
                    return true;
                }
            } else if (cap_setid == CAP_SETGID) {
                if (extent->lower_first == current_fsgid()) {
                    return true;
                }
            }
        }
    }

    if (!ns_capable(ns->parent, cap_setid)) {
        return false;
    }

    // Check if the opener has the capability to grant the mapping
    struct inode *inode = file_inode(file);
    if (inode && ns_capable(inode->i_sb->s_user_ns, cap_setid)) {
        return true;
    }

    return false;
}

bool check_new_id_mapping_permitted(const struct file *file,
                                    struct user_namespace *ns,
                                    int cap_setid,
                                    struct uid_gid_map *new_map)
{
    if (new_map->nr_extents == 1 &&
        new_map->map[0].lower_first == new_map->lowest_mapped &&
        new_map->map[0].count == 1) {
        return true;
    }

    if (cap_setid == CAP_SETUID) {
        if (ns->uid_mapping_permitted &&
            ns->uid_eq(file->f_cred->uid, new_map->lowest_mapped)) {
            return true;
        }
    } else if (cap_setid == CAP_SETGID) {
        if (ns->gid_mapping_permitted &&
            ns->gid_eq(file->f_cred->gid, new_map->lowest_mapped)) {
            return true;
        }
    }

    return ns->has_cap && file->f_op->can_set_mapping(new_map);
}

bool check_new_id_mapping(const struct file *file, struct user_namespace *ns,
                          int cap_setid, struct uid_gid_map *new_map)
{
    struct user_namespace *old_ns = ns->parent;
    kuid_t *old_id = cap_setid == CAP_SETUID ? &new_map->lowest_id : &new_map->lowest_id;
    kgid_t *new_id = cap_setid == CAP_SETUID ? &new_map->lowest_id : &new_map->lowest_id;

    if (new_map->nr_extents == 1 && new_map->extents[0].count == 1 &&
        (cap_setid == CAP_SETUID ? kuid_eq(*old_id, current_uid()) : kgid_eq(*new_id, current_gid())))
        return true;

    if (!ns_capable(old_ns, cap_setid))
        return false;

    if (!ns_capable(current_user_ns(), cap_setid))
        return false;

    return true;
}

bool check_new_id_mapping_permitted(const struct file *file,
                                    struct user_namespace *ns,
                                    int cap_setid,
                                    struct uid_gid_map *new_map)
{
    if (new_map->nr_extents == 1) {
        struct uid_gid_map_entry *entry = &new_map->extents[0];
        if (entry->count == 1) {
            kuid_t fsuid = current_fsuid();
            kgid_t fsgid = current_fsgid();

            if (cap_setid == CAP_SETUID && kuid_eq(entry->lower, fsuid)) {
                return true;
            }
            if (cap_setid == CAP_SETGID && kgid_eq(entry->lower, fsgid)) {
                return true;
            }
        }
    }

    if (ns == &init_user_ns) {
        return true;
    }

    if (ns->parent &&
        ns_capable(ns->parent, cap_setid) &&
        file_ns_capable(file, cap_setid)) {
        return true;
    }

    return false;
}
